<template><div class="allocation"><div class="allocation-heading"><strong>{{title}}</strong><el-button size="small" plain @click="addRow">Add allocation</el-button></div><div v-for="(row,index) in draft" :key="row.client_key||index" class="allocation-row"><el-form-item :label="selectLabel" required><el-select :model-value="row[referenceKey]" @update:model-value="setValue(index,referenceKey,$event)"><el-option v-for="option in options" :key="option.value" :label="option.label" :value="option.value"/></el-select></el-form-item><el-form-item label="Percentage" required><el-input-number :model-value="row.percentage" :min="0" :max="100" @update:model-value="setValue(index,'percentage',$event)"/></el-form-item><el-button v-if="draft.length>1" text type="danger" @click="removeRow(index)"><v-icon>mdi-close</v-icon></el-button></div><p :class="total===100?'total valid':'total invalid'">{{totalLabel}}: {{total}}%</p></div></template><script>export default {props:{modelValue:{type:Array,default:()=>[]},options:{type:Array,default:()=>[]},referenceKey:{type:String,required:true},title:{type:String,default:'Allocation'},selectLabel:{type:String,default:'Party'},totalLabel:{type:String,default:'Total'},responsibilityType:{type:String,default:''}},emits:['update:modelValue'],data(){return{draft:this.copy(this.modelValue)}},computed:{total(){return this.draft.reduce((sum,row)=>sum+(Number(row.percentage)||0),0)}},watch:{modelValue:{deep:true,handler(value){this.draft=this.copy(value)}}},methods:{copy(value){return JSON.parse(JSON.stringify(value||[]))},key(prefix){return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`},notify(){this.$emit('update:modelValue',this.copy(this.draft))},setValue(index,key,value){this.draft[index][key]=value;this.notify()},addRow(){this.draft.push({client_key:this.key('allocation'),id:null,[this.referenceKey]:'',percentage:Math.max(0,100-this.total),...(this.responsibilityType?{responsibility_type:this.responsibilityType}:{})});this.notify()},removeRow(index){this.draft.splice(index,1);this.notify()}}}</script>
